// ICSE 10 Mathematics ch13 Equation of a Straight Line — practice bank with independent re-solve checks.
// Keys, option values and final equations are typed as literals; each check recomputes them from the givens with
// line.mjs (exact fractions): slopes by the two-point formula, lines by point-slope AND two-point determinant
// form, parallel/perpendicular by coefficients AND slopes, meeting points by Cramer's rule substituted back,
// mid-points, section points, centroids, medians, altitudes and perpendicular bisectors with their own
// cross-checks. Typed equations are parsed back into lines (lineOfTex) and compared exactly. Every typed
// working line is checked: numeric lines and equations in one unknown by work.mjs, equations of a line by
// lsteps (each step must have exactly the computed line as its graph). MCQ distractors are recomputed from the
// slip they represent.
import { Q, mk, r } from './lib.mjs';
import { F, pt, slope, through, join, meet, isParallel, isPerp, parallelThrough, perpThrough, perpSlope, mid, section, centroid, perpBisector, median, altitude, slopeOf, yInt, xInt, yAt, on, sameLine, line, key, lineOfTex, eqTex, d2, lsteps } from './line.mjs';
import { steps, ARITH, eqctx } from './work.mjs';

const J = (lines) => lines.join('\n\n');
const A = (lines) => steps(ARITH, lines);
const W = (ctx, lines) => steps(ctx, lines);
const P = (x, y) => pt(x, y);
const LS = (L, lines) => lsteps(L, lines);
/** Option values of typed equations. */
const eqv = (texs) => texs.map((t) => key(lineOfTex(t)));
/** A typed final equation must be the computed line and appear in the model answer. */
const eqIn = (C, tex, L, what = 'equation') => { C.assert(sameLine(lineOfTex(tex), L), `${what} ${tex} is ${eqTex(L)}`); C.model([tex]); };
const deg = (m) => Math.round((((Math.atan(m) * 180) / Math.PI + 180) % 180) * 1e9) / 1e9;
const tanD = (t) => Math.tan((t * Math.PI) / 180);
const pq = (p) => [p[0].num(), p[1].num()];

// =============================================================== MCQ
const o01 = [1, Math.sqrt(3), 1 / Math.sqrt(3), 0];
Q('m01', mk.mcq({ stem: r`A straight line makes an angle of $45^\circ$ with the positive direction of the $x$-axis. What is its slope?`, opts: ['$1$', r`$\sqrt{3}$`, r`$\dfrac{1}{\sqrt{3}}$`, '$0$'], key: 'a', sol: r`The slope is the tangent of the inclination: $m = \tan 45^\circ = 1$. Option (b) is $\tan 60^\circ$, (c) is $\tan 30^\circ$ and (d) is the slope of a horizontal line.`, d: 1, c: 'recall', t: [1], time: 45 }), (C) => { C.assert(Math.abs(tanD(60) - o01[1]) < 1e-12 && Math.abs(tanD(30) - o01[2]) < 1e-12 && tanD(0) === 0, 'distractors tan 60°, tan 30°, tan 0°'); C.which(o01, tanD(45)); });

const a02 = P(2, -3), b02 = P(6, 5), w02 = A([r`\dfrac{5 - (-3)}{6 - 2} = \dfrac{8}{4} = 2`]), o02 = [2, 0.5, -2, 1];
Q('m02', mk.mcq({ stem: r`What is the gradient of the segment that runs from $(2, -3)$ to $(6, 5)$?`, opts: ['$2$', r`$\dfrac{1}{2}$`, '$-2$', '$1$'], key: 'a', sol: r`Rise over run: $m = ${w02.lines[0]}$. Option (b) divides the run by the rise, (c) subtracts the $y$-values and the $x$-values in opposite orders, and (d) adds the $x$-coordinates instead of subtracting them.`, d: 1, c: 'understanding', t: [1], time: 60 }), (C) => { w02.verify(C); const run = b02[0].sub(a02[0]), rise = b02[1].sub(a02[1]); C.assert(run.div(rise).num() === o02[1] && rise.div(a02[0].sub(b02[0])).num() === o02[2] && rise.div(b02[0].add(a02[0])).num() === o02[3], 'distractors'); C.which(o02, slope(a02, b02).num()); });

const L03 = [join(P(3, -1), P(3, 4)), join(P(-1, 3), P(4, 3)), join(P(0, 0), P(3, 3)), lineOfTex('y = 3x')];
Q('m03', mk.mcq({ stem: r`For which of these lines is the slope not defined?`, opts: [r`the line through $(3, -1)$ and $(3, 4)$`, r`the line through $(-1, 3)$ and $(4, 3)$`, r`the line through $(0, 0)$ and $(3, 3)$`, r`the line $y = 3x$`], key: 'a', sol: r`When two points share their $x$-coordinate, $x_2 - x_1 = 0$ and the slope formula would divide by zero: the line $x = 3$ is vertical and has no slope. Option (b) is horizontal, with slope $0$; (c) and (d) have slopes $1$ and $3$.`, d: 2, c: 'understanding', t: [1], time: 45 }), (C) => { C.assert(slopeOf(L03[1]).eq(0) && slopeOf(L03[2]).eq(1) && slopeOf(L03[3]).eq(3) && sameLine(L03[0], line(1, 0, -3)), 'other slopes 0, 1, 3; (a) is x = 3'); C.which(L03.map((L) => (slopeOf(L) === null ? 'undefined' : 'defined')), 'undefined'); });

const L04 = lineOfTex('y = -4x + 7'), o04 = [[-4, 7], [7, -4], [4, 7], [-4, -7]];
Q('m04', mk.mcq({ stem: r`Compare $y = -4x + 7$ with $y = mx + c$. Which pair gives its slope and its $y$-intercept?`, opts: [r`$m = -4$, $c = 7$`, r`$m = 7$, $c = -4$`, r`$m = 4$, $c = 7$`, r`$m = -4$, $c = -7$`], key: 'a', sol: r`In $y = mx + c$ the coefficient of $x$ is the slope and the constant term is the $y$-intercept, signs included: $m = -4$ and $c = 7$. Option (b) swaps them; (c) and (d) each drop a sign.`, d: 1, c: 'recall', t: [2], time: 45 }), (C) => { C.which(o04, [slopeOf(L04).num(), yInt(L04).num()]); });

const L05 = lineOfTex('5x - 2y + 6 = 0'), o05 = [2.5, -2.5, 0.4, 5], w05 = LS(L05, [r`2y = 5x + 6 \Rightarrow y = \dfrac{5}{2}x + 3`]);
Q('m05', mk.mcq({ stem: r`The gradient of the line $5x - 2y + 6 = 0$ equals`, opts: [r`$\dfrac{5}{2}$`, r`$-\dfrac{5}{2}$`, r`$\dfrac{2}{5}$`, '$5$'], key: 'a', sol: r`Make $y$ the subject: ${w05.md[0]}, so $m = \dfrac{5}{2}$. Option (b) drops the minus sign of the $y$-term, (c) turns the fraction upside down and (d) is only the coefficient of $x$.`, d: 2, c: 'understanding', t: [2], time: 60 }), (C) => { w05.verify(C); C.assert(F(-5, -2).neg().num() === o05[1] && F(2, 5).num() === o05[2], 'distractors'); C.which(o05, slopeOf(L05).num()); });

const L06 = lineOfTex('3x + 4y - 12 = 0'), o06 = [3, 4, -3, 12], w06 = W(eqctx('y', [3]), [r`4y - 12 = 0 \Rightarrow y = 3`]);
Q('m06', mk.mcq({ stem: r`The line $3x + 4y - 12 = 0$ cuts the $y$-axis at a height of`, opts: ['$3$', '$4$', '$-3$', '$12$'], key: 'a', sol: r`On the $y$-axis $x = 0$, so ${w06.md[0]}. Option (b) is where the line cuts the $x$-axis, (c) has the wrong sign and (d) is the constant term.`, d: 2, c: 'understanding', t: [2], time: 60 }), (C) => { w06.verify(C); C.assert(xInt(L06).num() === o06[1], '(b) is the x-intercept'); C.which(o06, yInt(L06).num()); });

const L07 = through(P(-1, 2), 3), o07 = ['3x - y + 5 = 0', '3x - y - 5 = 0', '3x + y + 1 = 0', 'x - 3y + 7 = 0'], w07 = LS(L07, [r`y - 2 = 3(x + 1) \Rightarrow y - 2 = 3x + 3 \Rightarrow 3x - y + 5 = 0`]);
Q('m07', mk.mcq({ stem: r`Which equation describes the line of slope $3$ passing through $(-1, 2)$?`, opts: o07.map((e) => `$${e}$`), key: 'a', sol: r`Point-slope form: ${w07.md[0]}. Option (b) is the line of slope $3$ through $(1, -2)$, (c) has slope $-3$ and (d) has slope $\dfrac{1}{3}$.`, d: 2, c: 'application', t: [3], time: 75 }), (C) => { w07.verify(C); const v = eqv(o07); C.assert(v[1] === key(through(P(1, -2), 3)) && v[2] === key(through(P(-1, 2), -3)) && v[3] === key(through(P(-1, 2), F(1, 3))), 'distractors'); C.which(v, key(L07)); });

const L08 = join(P(0, -3), P(4, 5)), o08 = ['y = 2x - 3', 'y = -2x - 3', 'y = 2x + 3', r`y = \dfrac{1}{2}x - 3`], w08 = A([r`\dfrac{5 - (-3)}{4 - 0} = 2`]);
Q('m08', mk.mcq({ stem: r`The line joining $A(0, -3)$ and $B(4, 5)$ has the equation`, opts: o08.map((e) => `$${e}$`), key: 'a', sol: r`Slope $m = ${w08.lines[0]}$, and $A$ is on the $y$-axis, so $c = -3$: the line is $y = 2x - 3$. Option (b) has the wrong sign of the slope, (c) the wrong sign of the intercept and (d) the slope upside down.`, d: 2, c: 'application', t: [3], time: 75 }), (C) => { w08.verify(C); C.assert(yInt(L08).eq(-3), 'c = −3'); C.which(eqv(o08), key(L08)); });

const G09 = lineOfTex('2x - 3y + 4 = 0'), o09 = ['4x - 6y - 1 = 0', '3x - 2y + 4 = 0', '3x + 2y - 5 = 0', '2x + 3y + 4 = 0'];
Q('m09', mk.mcq({ stem: r`Which of these lines is parallel to $2x - 3y + 4 = 0$?`, opts: o09.map((e) => `$${e}$`), key: 'a', sol: r`The given line has slope $\dfrac{2}{3}$. The line $4x - 6y - 1 = 0$ has slope $\dfrac{4}{6} = \dfrac{2}{3}$ too, and a different intercept, so it is parallel. Option (c) has slope $-\dfrac{3}{2}$ and is perpendicular to the given line; (b) and (d) have slopes $\dfrac{3}{2}$ and $-\dfrac{2}{3}$.`, d: 2, c: 'understanding', t: [4], time: 75 }), (C) => { A([r`\dfrac{4}{6} = \dfrac{2}{3}`]).verify(C); const v = o09.map((t) => { const M = lineOfTex(t); return isParallel(M, G09) ? 'parallel' : isPerp(M, G09) ? 'perpendicular' : 'neither'; }); C.assert(v[2] === 'perpendicular', '(c) perpendicular'); C.which(v, 'parallel'); });

const m10 = slope(P(1, 4), P(5, 2)), o10 = [2, -2, 0.5, -0.5], w10 = A([r`\dfrac{2 - 4}{5 - 1} = -\dfrac{1}{2}`, r`-\dfrac{1}{2} \times 2 = -1`]);
Q('m10', mk.mcq({ stem: r`A line is drawn at right angles to the segment joining $(1, 4)$ and $(5, 2)$. What is its slope?`, opts: ['$2$', '$-2$', r`$\dfrac{1}{2}$`, r`$-\dfrac{1}{2}$`], key: 'a', sol: r`The segment has slope ${w10.md[0]}. A perpendicular slope multiplies with it to give $-1$: ${w10.md[1]}, so the answer is $2$. Option (d) is the slope of the segment itself, and (b) changes its sign without inverting it.`, d: 2, c: 'understanding', t: [4], time: 60 }), (C) => { w10.verify(C); C.assert(m10.num() === o10[3], '(d) is the segment slope'); C.which(o10, slopeOf(perpThrough(join(P(1, 4), P(5, 2)), P(0, 0))).num()); });

const G11 = lineOfTex('6x - 4y + 1 = 0'), o11 = [-2, 2, 4.5, -4.5], w11 = W(eqctx('k', [-2]), [r`-\dfrac{3}{k} = \dfrac{6}{4} \Rightarrow 6k = -12 \Rightarrow k = -2`]);
Q('m11', mk.mcq({ stem: r`For what value of $k$ is the line $3x + ky - 2 = 0$ parallel to $6x - 4y + 1 = 0$?`, opts: ['$-2$', '$2$', r`$\dfrac{9}{2}$`, r`$-\dfrac{9}{2}$`], key: 'a', sol: r`Parallel lines have equal slopes: ${w11.md[0]}. Option (c) is the value that makes the two lines perpendicular, and (b) loses the minus sign.`, d: 3, c: 'application', t: [4], time: 90 }), (C) => { w11.verify(C); const v = o11.map((k) => { const M = line(3, k, -2); return isParallel(M, G11) ? 'parallel' : isPerp(M, G11) ? 'perpendicular' : 'neither'; }); C.assert(v[2] === 'perpendicular', '(c) perpendicular'); C.which(v, 'parallel'); });

const G12 = lineOfTex('4x + 6y - 1 = 0'), o12 = [3, -3, F(-4, 3), 12], w12 = W(eqctx('p', [3]), [r`\dfrac{p}{2} \times \left(-\dfrac{2}{3}\right) = -1 \Rightarrow p = 3`]);
Q('m12', mk.mcq({ stem: r`Find $p$ so that the lines $px - 2y + 5 = 0$ and $4x + 6y - 1 = 0$ cut each other at right angles.`, opts: ['$3$', '$-3$', r`$-\dfrac{4}{3}$`, '$12$'], key: 'a', sol: r`The slopes are $\dfrac{p}{2}$ and $-\dfrac{4}{6} = -\dfrac{2}{3}$. For perpendicular lines their product is $-1$: ${w12.md[0]}. Option (c) makes the slopes equal, which gives parallel lines instead.`, d: 3, c: 'application', t: [4], time: 90 }), (C) => { w12.verify(C); A([r`-\dfrac{4}{6} = -\dfrac{2}{3}`]).verify(C); const v = o12.map((p) => { const M = line(p, -2, 5); return isPerp(M, G12) ? 'perpendicular' : isParallel(M, G12) ? 'parallel' : 'neither'; }); C.assert(v[2] === 'parallel', '(c) parallel'); C.which(v, 'perpendicular'); });

const a13 = P(2, 5), b13 = P(6, 1), L13 = perpBisector(a13, b13), o13 = ['x - y - 1 = 0', 'x + y - 7 = 0', 'x - y + 1 = 0', 'x + y - 1 = 0'], w13 = A([r`\dfrac{1 - 5}{6 - 2} = -1`, r`\dfrac{2 + 6}{2} = 4`, r`\dfrac{5 + 1}{2} = 3`]), w13b = LS(L13, ['y - 3 = x - 4']);
Q('m13', mk.mcq({ stem: r`Which equation is the perpendicular bisector of the segment from $(2, 5)$ to $(6, 1)$?`, opts: o13.map((e) => `$${e}$`), key: 'a', sol: r`The mid-point is $(4, 3)$, since ${w13.md[1]} and ${w13.md[2]}. The segment has slope ${w13.md[0]}, so the bisector has slope $1$: ${w13b.md[0]}, that is $x - y - 1 = 0$. Option (b) is the line through the two given points.`, d: 3, c: 'application', t: [4, 5], time: 90 }), (C) => { w13.verify(C); w13b.verify(C); C.assert(same2(mid(a13, b13), [4, 3]) && eqv(o13)[1] === key(join(a13, b13)), 'mid-point; (b) is AB'); C.which(eqv(o13), key(L13)); });

const A14 = P(0, 4), B14 = P(-2, 0), C14 = P(6, 0), L14 = median(A14, B14, C14), o14 = ['2x + y - 4 = 0', 'x = 0', '2x + 3y - 12 = 0', '2x - y + 4 = 0'], w14 = A([r`\dfrac{-2 + 6}{2} = 2`, r`\dfrac{0 - 4}{2 - 0} = -2`]);
Q('m14', mk.mcq({ stem: r`Triangle $ABC$ has vertices $A(0, 4)$, $B(-2, 0)$ and $C(6, 0)$. The median drawn from $A$ lies along`, opts: o14.map((e) => `$${e}$`), key: 'a', sol: r`The median from $A$ goes to the mid-point of $BC$, which is $(2, 0)$ because ${w14.md[0]}. Its slope is ${w14.md[1]} and its $y$-intercept is $4$, so it is $y = -2x + 4$, or $2x + y - 4 = 0$. Option (b) is the altitude from $A$, (c) is the side $AC$ and (d) is the side $AB$.`, d: 3, c: 'analysis', t: [5], time: 90 }), (C) => { w14.verify(C); const v = eqv(o14); C.assert(v[1] === key(altitude(A14, B14, C14)) && v[2] === key(join(A14, C14)) && v[3] === key(join(A14, B14)), 'distractors: altitude, AC, AB'); C.which(v, key(L14)); });

const o15 = [-4, 4, -1, 1], w15 = W(eqctx('m', [-4]), [r`-5 = 2m + 3 \Rightarrow 2m = -8 \Rightarrow m = -4`]);
Q('m15', mk.mcq({ stem: r`The line $y = mx + 3$ goes through the point $(2, -5)$. Then $m$ is`, opts: ['$-4$', '$4$', '$-1$', '$1$'], key: 'a', sol: r`Substitute the point: ${w15.md[0]}. Option (c) comes from adding $3$ instead of subtracting it, and (b) loses the sign.`, d: 2, c: 'application', t: [2], time: 60 }), (C) => { w15.verify(C); C.assert(F(-5 + 3, 2).num() === o15[2], '(c) slip'); C.which(o15, slope(P(0, 3), P(2, -5)).num()); });

const o16 = [60, 30, 45, 120];
Q('m16', mk.mcq({ stem: r`The line $\sqrt{3}x - y + 2 = 0$ is inclined to the positive $x$-axis at an angle of`, opts: o16.map((v) => `$${v}^\\circ$`), key: 'a', sol: r`Writing it as $y = \sqrt{3}x + 2$ shows that $m = \sqrt{3}$. Since $\tan 60^\circ = \sqrt{3}$, the inclination is $60^\circ$. Option (b) is the angle whose tangent is $\dfrac{1}{\sqrt{3}}$, and (d) would need a negative slope.`, d: 2, c: 'understanding', t: [1, 2], time: 60 }), (C) => { C.assert(tanD(120) < 0 && Math.abs(tanD(30) - 1 / Math.sqrt(3)) < 1e-12, 'distractors'); C.which(o16, deg(Math.sqrt(3))); });

const L17 = lineOfTex('2x - 5y = 10'), o17 = [[5, 0], [0, -2], [-5, 0], [2, 0]];
Q('m17', mk.mcq({ stem: r`At which point does the graph of $2x - 5y = 10$ meet the $x$-axis?`, opts: o17.map(([x, y]) => `$(${x}, ${y})$`), key: 'a', sol: r`On the $x$-axis $y = 0$, so $2x = 10$ and $x = 5$: the point is $(5, 0)$. Option (b) is where the line meets the $y$-axis.`, d: 2, c: 'understanding', t: [2], time: 60 }), (C) => { C.assert(o17[1][1] === yInt(L17).num() && on(L17, P(...o17[1])), '(b) is the y-axis point'); C.which(o17, [xInt(L17).num(), 0]); });

const L18 = join(P(-1, -1), P(2, 5)), o18 = [9, 7, 11, 3], w18 = A([r`\dfrac{5 - (-1)}{2 - (-1)} = 2`]), w18b = W(eqctx('k', [9]), [r`\dfrac{k - 5}{4 - 2} = 2 \Rightarrow k - 5 = 4 \Rightarrow k = 9`]);
Q('m18', mk.mcq({ stem: r`If $A(-1, -1)$, $B(2, 5)$ and $C(4, k)$ lie on one straight line, then $k$ equals`, opts: ['$9$', '$7$', '$11$', '$3$'], key: 'a', sol: r`Slope of $AB$: ${w18.md[0]}. For $C$ to be on the same line, the slope of $BC$ must also be $2$: ${w18b.md[0]}. Option (b) takes $k - 5 = 2$, forgetting the run of $2$.`, d: 3, c: 'application', t: [1], time: 75 }), (C) => { w18.verify(C); w18b.verify(C); C.which(o18, yAt(L18, 4).num()); C.assert(on(L18, P(4, 9)) && !on(L18, P(4, 7)), 'C on AB only for k = 9'); });

// =============================================================== assertion-reason (keys a c d b a c)
const war1 = A([r`\dfrac{-6 - 2}{1 - (-3)} = \dfrac{-8}{4} = -2`]);
Q('ar1', mk.ar({ a: r`The line through $(-3, 2)$ and $(1, -6)$ has slope $-2$.`, r: r`The slope of the line through $(x_1, y_1)$ and $(x_2, y_2)$, where $x_1 \ne x_2$, is $\dfrac{y_2 - y_1}{x_2 - x_1}$.`, key: 'c', sol: r`A is true: ${war1.md[0]}. R is the two-point slope formula, and A is obtained by applying it, so R explains A.`, d: 2, c: 'understanding', t: [1] }), (C) => { war1.verify(C); C.assert(slope(P(-3, 2), P(1, -6)).eq(-2), 'A true'); C.key('c'); });

const L_ar2 = lineOfTex('4x + 2y - 9 = 0');
Q('ar2', mk.ar({ a: r`The slope of the line $4x + 2y - 9 = 0$ is $-2$.`, r: r`The $y$-intercept of the line $ax + by + c = 0$ is $\dfrac{c}{b}$.`, key: 'a', sol: r`A is true: $2y = -4x + 9$ gives $y = -2x + \dfrac{9}{2}$. R is false: putting $x = 0$ gives $by = -c$, so the $y$-intercept is $-\dfrac{c}{b}$; here it is $\dfrac{9}{2}$, not $-\dfrac{9}{2}$.`, d: 2, c: 'understanding', t: [2] }), (C) => { LS(L_ar2, [r`2y = -4x + 9`, r`y = -2x + \dfrac{9}{2}`]).verify(C); C.assert(slopeOf(L_ar2).eq(-2) && yInt(L_ar2).eq(F(9, 2)) && !yInt(L_ar2).eq(F(-9, 2)), 'A true; R gives the wrong sign'); C.key('a'); });

const L3a = lineOfTex('2x - y + 3 = 0'), L3b = lineOfTex('x - 2y - 1 = 0');
Q('ar3', mk.ar({ a: r`The lines $2x - y + 3 = 0$ and $x - 2y - 1 = 0$ are perpendicular.`, r: r`Two lines, neither of them vertical, are perpendicular exactly when the product of their slopes is $-1$.`, key: 'b', sol: r`R is true. A is false: the slopes are $2$ and $\dfrac{1}{2}$, whose product is $2 \times \dfrac{1}{2} = 1$, not $-1$.`, d: 2, c: 'analysis', t: [4] }), (C) => { A([r`2 \times \dfrac{1}{2} = 1`]).verify(C); C.assert(slopeOf(L3a).eq(2) && slopeOf(L3b).eq(F(1, 2)) && !isPerp(L3a, L3b), 'A false'); C.key('b'); });

Q('ar4', mk.ar({ a: r`The line through $(2, 3)$ and $(-4, 3)$ has the equation $y = 3$.`, r: r`Every line through the origin, other than the $y$-axis, has an equation of the form $y = mx$.`, key: 'd', sol: r`A is true: both points have $y$-coordinate $3$, so the line is horizontal, $y = 3$. R is also true (the $y$-intercept of such a line is $0$), but the line in A does not pass through the origin, so R does not explain A.`, d: 3, c: 'analysis', t: [2, 3] }), (C) => { const L = join(P(2, 3), P(-4, 3)); C.assert(sameLine(L, lineOfTex('y = 3')) && !on(L, P(0, 0)), 'A true; not through O'); C.key('d'); });

const L_ar5 = perpBisector(P(1, 2), P(5, 2));
Q('ar5', mk.ar({ a: r`The perpendicular bisector of the segment joining $(1, 2)$ and $(5, 2)$ is the line $x = 3$.`, r: r`The perpendicular bisector of a segment passes through its mid-point and is at right angles to the segment.`, key: 'c', sol: r`The segment is horizontal with mid-point $(3, 2)$. By R its bisector is the vertical line through $(3, 2)$, which is $x = 3$. Both are true and R explains A.`, d: 2, c: 'understanding', t: [5] }), (C) => { C.assert(sameLine(L_ar5, lineOfTex('x = 3')), 'A true'); C.key('c'); });

const L_ar6 = parallelThrough(lineOfTex('y = -2x + 1'), P(0, 5));
Q('ar6', mk.ar({ a: r`The line through $(0, 5)$ parallel to $y = -2x + 1$ is $2x + y - 5 = 0$.`, r: r`Two parallel lines always have the same $y$-intercept.`, key: 'a', sol: r`A is true: the required line has slope $-2$ and $y$-intercept $5$, so $y = -2x + 5$. R is false: parallel lines share the slope, not the intercept; equal intercepts as well would make them the same line.`, d: 2, c: 'understanding', t: [4] }), (C) => { C.assert(sameLine(L_ar6, lineOfTex('2x + y - 5 = 0')) && !yInt(L_ar6).eq(1), 'A true; intercepts differ'); C.key('a'); });

// =============================================================== true-false
Q('tf1', mk.tf({ stem: r`Every line parallel to the $x$-axis has slope $0$.`, key: 't', sol: r`True. All its points have the same $y$-coordinate, so the rise between any two of them is $0$, and the inclination is $0^\circ$, with $\tan 0^\circ = 0$.`, d: 1, c: 'recall', t: [1] }), (C) => { C.assert([-4, 0, 7].every((b) => slopeOf(line(0, 1, b)).eq(0)) && slope(P(-2, 6), P(9, 6)).eq(0), 'horizontal slopes'); C.key('t'); });

const L_tf2 = lineOfTex('3x - y = 6');
Q('tf2', mk.tf({ stem: r`The line $3x - y = 6$ crosses the $y$-axis at $(0, 6)$.`, key: 'f', sol: r`False. Putting $x = 0$ gives $-y = 6$, so the line crosses the $y$-axis at $(0, -6)$.`, d: 2, c: 'understanding', t: [2] }), (C) => { C.assert(yInt(L_tf2).eq(-6) && !on(L_tf2, P(0, 6)), 'y-intercept −6'); C.key('f'); });

const wtf3 = A([r`2 \times 4 + 3 \times (-1) - 5 = 8 - 3 - 5 = 0`]);
Q('tf3', mk.tf({ stem: r`The point $(4, -1)$ satisfies $2x + 3y - 5 = 0$, so it lies on that line.`, key: 't', sol: r`True. Substituting: ${wtf3.md[0]}.`, d: 1, c: 'understanding', t: [2, 3] }), (C) => { wtf3.verify(C); C.assert(on(lineOfTex('2x + 3y - 5 = 0'), P(4, -1)), 'on the line'); C.key('t'); });

const wtf4 = A([r`\dfrac{3}{4} \times \left(-\dfrac{4}{3}\right) = -1`]);
Q('tf4', mk.tf({ stem: r`Two lines whose slopes are $\dfrac{3}{4}$ and $-\dfrac{4}{3}$ meet at right angles.`, key: 't', sol: r`True: ${wtf4.md[0]}.`, d: 2, c: 'understanding', t: [4] }), (C) => { wtf4.verify(C); C.assert(isPerp(through(P(0, 0), F(3, 4)), through(P(1, 1), F(-4, 3))), 'perpendicular'); C.key('t'); });

const wtf5 = A([r`\dfrac{1 - 7}{4 - 1} = \dfrac{-6}{3} = -2`]);
Q('tf5', mk.tf({ stem: r`The gradient of the line joining $(1, 7)$ and $(4, 1)$ is $2$.`, key: 'f', sol: r`False. $m = ${wtf5.lines[0]}$; the line falls from left to right.`, d: 2, c: 'understanding', t: [1] }), (C) => { wtf5.verify(C); C.assert(slope(P(1, 7), P(4, 1)).eq(-2), 'slope −2'); C.key('f'); });

const wtf6 = A([r`\dfrac{4 + 6}{2} = 5`, r`\dfrac{5 + (-3)}{2} = 1`]);
Q('tf6', mk.tf({ stem: r`In triangle $ABC$ with $A(1, 1)$, $B(4, 5)$ and $C(6, -3)$, the median from $A$ passes through $(5, 1)$.`, key: 't', sol: r`True. The median from $A$ ends at the mid-point of $BC$, whose coordinates are ${wtf6.md[0]} and ${wtf6.md[1]}.`, d: 2, c: 'application', t: [5] }), (C) => { wtf6.verify(C); C.assert(on(median(P(1, 1), P(4, 5), P(6, -3)), P(5, 1)), 'on the median'); C.key('t'); });

