Q('fb2', mk.fill({ stem: r`For the line $y = \dfrac{1}{2}x - 7$, the $y$-intercept is ___.`, acc: [['-7', '−7']], sol: r`Comparing with $y = mx + c$ gives $c = -7$.`, d: 1, c: 'recall', t: [2] }), (C) => { C.blank(yInt(lineOfTex(r`y = \dfrac{1}{2}x - 7`)).num()); });

const wfb3 = W(eqctx('c', [-5]), [r`1 = 3 \times 2 + c \Rightarrow c = 1 - 6 = -5`]);
