Q('fb4', mk.fill({ stem: r`Any line perpendicular to $y = 5x - 2$ has slope ___.`, acc: [['-1/5', '−1/5', '-0.2', '−0.2']], sol: r`Perpendicular slopes multiply to $-1$: $5m = -1$, so $m = -1/5$, that is $-0.2$.`, d: 2, c: 'understanding', t: [4] }), (C) => { C.blank(perpSlope(slopeOf(lineOfTex('y = 5x - 2'))).num()); });

