const A_n5 = P(2, 6), B_n5 = P(-4, 0), C_n5 = P(6, -2), L_n5 = median(A_n5, B_n5, C_n5), wn5 = A([r`\dfrac{-4 + 6}{2} = 1`, r`\dfrac{0 + (-2)}{2} = -1`, r`\dfrac{6 - (-1)}{2 - 1} = 7`]), wn5b = LS(L_n5, [r`y - 6 = 7(x - 2) \Rightarrow y = 7x - 8`]);
