Q('n06', mk.num({ stem: r`The lines $2x + 3y = 7$ and $3x - 2y = 4$ meet at a point $P$. Find the $x$-coordinate of $P$.`, value: 2, sol: r`Multiply the first equation by $2$ and the second by $3$, then add to remove $y$: ${wn6.md[0]}.`, scheme: [['x = 2', 1]], d: 2, c: 'application', t: [4], time: 90 }), (C) => { wn6.verify(C); C.val(p_n6[0].num()); });

