const L203 = through(P(2, -4), -1), w203 = LS(L203, [r`y + 4 = -(x - 2) \Rightarrow y + 4 = -x + 2 \Rightarrow x + y + 2 = 0`]);
Q('s203', mk.short({ marks: 2, stem: r`A line through $(2, -4)$ makes an angle of $135^\circ$ with the positive $x$-axis. Find its equation.`, model: J([r`Slope: $m = \tan 135^\circ = -1$ (an obtuse inclination gives a negative slope).`, r`Point-slope form: ${w203.md[0]}.`]), sol: r`Turn the inclination into a slope with $m = \tan \theta$, then use the point-slope form.`, scheme: [['m = −1', 1], ['x + y + 2 = 0', 1]], d: 2, c: 'application', t: [1, 3], time: 120 }), (C) => { w203.verify(C); C.assert(Math.abs(tanD(135) + 1) < 1e-12 && deg(-1) === 135, 'tan 135° = −1'); eqIn(C, 'x + y + 2 = 0', L203); });

const L204 = join(P(1, -2), P(4, 4)), G204 = lineOfTex('2x - y + 7 = 0'), w204 = A([r`\dfrac{4 - (-2)}{4 - 1} = \dfrac{6}{3} = 2`, r`2 \times 1 - (-2) + 7 = 11`]);
Q('s204', mk.short({ marks: 2, stem: r`Show that the line through $(1, -2)$ and $(4, 4)$ is parallel to the line $2x - y + 7 = 0$.`, model: J([r`Slope of the line through the points: ${w204.md[0]}. The given line is $y = 2x + 7$, with slope $2$ as well.`, r`The slopes are equal, and $(1, -2)$ is not on the given line (${w204.md[1]}, not $0$), so the lines are parallel and distinct.`]), sol: r`Compare the two slopes; check that the lines are not the same line.`, scheme: [['slope 2 for each line', 1], ['equal slopes, hence parallel', 1]], d: 2, c: 'application', t: [4], time: 90 }), (C) => { w204.verify(C); C.assert(isParallel(L204, G204), 'parallel and distinct'); C.model([2, 11]); });

const L205 = through(P(1, -3), -2), w205 = LS(L205, [r`y + 3 = -2(x - 1) \Rightarrow 2x + y + 1 = 0`]), w205b = A([r`2 \times (-3) + 5 + 1 = 0`]);
Q('s205', mk.short({ marks: 2, stem: r`Does the point $(-3, 5)$ lie on the line that passes through $(1, -3)$ with slope $-2$? Give a reason.`, model: J([r`The line: ${w205.md[0]}.`, r`Substituting $(-3, 5)$: ${w205b.md[0]}, so yes, the point lies on the line.`]), sol: r`Find the equation first, then test whether the point satisfies it.`, scheme: [['2x + y + 1 = 0', 1], ['substitution gives 0: yes', 1]], d: 2, c: 'understanding', t: [3], time: 90 }), (C) => { w205.verify(C); w205b.verify(C); C.assert(on(L205, P(-3, 5)), 'on the line'); eqIn(C, '2x + y + 1 = 0', L205); });

// =============================================================== short answer, 3 marks
const L301 = join(P(-2, 7), P(4, -5)), w301 = A([r`\dfrac{-5 - 7}{4 - (-2)} = \dfrac{-12}{6} = -2`]), w301b = LS(L301, [r`y - 7 = -2(x + 2) \Rightarrow y - 7 = -2x - 4 \Rightarrow 2x + y - 3 = 0`]);
