const P405 = P(0, 4), Q405 = P(-4, -3), R405 = P(6, 2), QR405 = join(Q405, R405), L405 = altitude(P405, Q405, R405), F405 = meet(L405, QR405), w405 = A([r`\dfrac{2 - (-3)}{6 - (-4)} = \dfrac{5}{10} = \dfrac{1}{2}`]), w405b = LS(L405, [r`y - 4 = -2(x - 0) \Rightarrow 2x + y - 4 = 0`]), w405c = LS(QR405, [r`y - 2 = \dfrac{1}{2}(x - 6) \Rightarrow x - 2y - 2 = 0`]), w405d = W(eqctx('x', [2]), [r`x - 2(4 - 2x) - 2 = 0 \Rightarrow 5x = 10 \Rightarrow x = 2`]);
