Q('s406', mk.short({ marks: 4, stem: r`$A(2, -1)$, $B(6, 1)$, $C(4, 5)$ and $D(0, 3)$ are the vertices of a quadrilateral. Using slopes only, show that $ABCD$ is a rectangle.`, model: J([r`$m_{AB} = ${w406.lines[0]}$ and $m_{DC} = ${w406.lines[1]}$, so $AB \parallel DC$.`, r`$m_{BC} = ${w406.lines[2]}$ and $m_{AD} = ${w406.lines[3]}$, so $BC \parallel AD$. Hence $ABCD$ is a parallelogram.`, r`$m_{AB} \times m_{BC} = ${w406.lines[4]}$, so $AB \perp BC$.`, r`A parallelogram with a right angle is a rectangle.`]), sol: r`Two pairs of parallel sides make a parallelogram; one pair of perpendicular adjacent sides makes it a rectangle.`, scheme: [['AB ∥ DC', 1], ['BC ∥ AD', 1], ['AB ⊥ BC', 1], ['conclusion: rectangle', 1]], d: 3, c: 'analysis', t: [4], time: 240 }), (C) => { w406.verify(C); const [ab, bc, cd, da] = [join(A406, B406), join(B406, C406), join(C406, D406), join(D406, A406)]; C.assert(isParallel(ab, cd) && isParallel(bc, da) && isPerp(ab, bc) && isPerp(cd, da), 'rectangle by slopes'); C.model([-1]); });

