const A_l5 = P(-1, 2), B_l5 = P(3, 4), C_l5 = P(5, 0), O_l5 = mid(A_l5, C_l5), D_l5 = pt(O_l5[0].mul(2).sub(B_l5[0]), O_l5[1].mul(2).sub(B_l5[1])), BD_l5 = join(B_l5, D_l5), N_l5 = parallelThrough(BD_l5, A_l5);
